create or replace function public.get_teacher_allocation_setup(p_school_id uuid)
returns jsonb language sql stable security definer set search_path=public,pg_temp as $$ select jsonb_build_object(
 'terms',coalesce((select jsonb_agg(jsonb_build_object('id',t.id,'academicYearId',t.academic_year_id,'name',t.name,'status',t.lifecycle_status) order by t.starts_on desc) from public.terms t where t.school_id=p_school_id),'[]'::jsonb),
 'teachers',coalesce((select jsonb_agg(distinct jsonb_build_object('id',u.id,'name',u.full_name,'email',u.email)) from public.school_memberships m join public.users u on u.id=m.user_id join public.roles r on r.id=m.role_id where m.school_id=p_school_id and m.status='ACTIVE' and u.is_active and r.code='TEACHER'),'[]'::jsonb),
 'offerings',coalesce((select jsonb_agg(jsonb_build_object('id',co.id,'academicYearId',co.academic_year_id,'classId',c.id,'className',c.class_name,'streamId',co.stream_id,'streamName',st.stream_name,'subjectCode',coalesce(so.school_subject_code,ss.subject_code),'subjectName',coalesce(so.display_name_override,ss.subject_name),'status',co.status) order by c.level,c.class_name,ss.subject_name) from public.class_subject_offerings co join public.academic_classes c on c.id=co.class_id left join public.class_streams st on st.id=co.stream_id join public.school_subject_offerings so on so.id=co.school_subject_offering_id left join public.system_subjects ss on ss.id=so.system_subject_id where co.school_id=p_school_id and co.status='ACTIVE' and so.status='ACTIVE'),'[]'::jsonb),
 'allocations',coalesce((select jsonb_agg(jsonb_build_object('id',ta.id,'termId',ta.term_id,'offeringId',ta.class_subject_offering_id,'teacherId',ta.teacher_id,'teacherName',u.full_name,'role',ta.allocation_role,'status',ta.status,'effectiveFrom',ta.effective_from,'effectiveTo',ta.effective_to) order by ta.created_at desc) from public.teacher_allocations ta join public.users u on u.id=ta.teacher_id where ta.school_id=p_school_id),'[]'::jsonb)
) where public.is_active_school_member(p_school_id) or public.is_active_platform_admin() $$;
create or replace function public.assign_teacher_to_offering(p_class_subject_offering_id uuid,p_term_id uuid,p_teacher_id uuid,p_allocation_role text default 'PRIMARY_SUBJECT_TEACHER',p_effective_from date default current_date)
returns uuid language plpgsql security definer set search_path=public,pg_temp as $$
declare v_offering public.class_subject_offerings; v_term public.terms; v_actor uuid; v_id uuid;
begin
 select * into v_offering from public.class_subject_offerings where id=p_class_subject_offering_id and status='ACTIVE';
 if v_offering.id is null or not public.is_school_admin_for(v_offering.school_id) then raise exception 'Active class subject offering unavailable'; end if;
 select * into v_term from public.terms where id=p_term_id and school_id=v_offering.school_id and academic_year_id=v_offering.academic_year_id;
 if v_term.id is null then raise exception 'Term does not belong to the offering academic year'; end if;
 if p_allocation_role not in ('PRIMARY_SUBJECT_TEACHER','CO_TEACHER','SUBJECT_MODERATOR') then raise exception 'Unsupported allocation role'; end if;
 if not exists(select 1 from public.school_memberships m join public.roles r on r.id=m.role_id join public.users u on u.id=m.user_id where m.school_id=v_offering.school_id and m.user_id=p_teacher_id and m.status='ACTIVE' and u.is_active and r.code='TEACHER') then raise exception 'Teacher must be an active school member with the Teacher system role'; end if;
 v_actor:=public.current_app_user_id();
 if p_allocation_role='PRIMARY_SUBJECT_TEACHER' then update public.teacher_allocations set status='INACTIVE',effective_to=p_effective_from-1,updated_at=now() where school_id=v_offering.school_id and term_id=p_term_id and class_subject_offering_id=v_offering.id and coalesce(stream_id,'00000000-0000-0000-0000-000000000000'::uuid)=coalesce(v_offering.stream_id,'00000000-0000-0000-0000-000000000000'::uuid) and status='ACTIVE' and allocation_role='PRIMARY_SUBJECT_TEACHER'; end if;
 insert into public.teacher_allocations(school_id,academic_year_id,term_id,teacher_id,class_subject_offering_id,stream_id,status,allocation_role,effective_from,created_by) values(v_offering.school_id,v_offering.academic_year_id,p_term_id,p_teacher_id,v_offering.id,v_offering.stream_id,'ACTIVE',p_allocation_role,p_effective_from,v_actor) returning id into v_id;
 insert into public.audit_logs(user_name,user_role,action,entity_type,entity_id,new_value) values(v_actor::text,'SCHOOL_ADMIN','TEACHER_ALLOCATED','teacher_allocation',v_id::text,jsonb_build_object('term_id',p_term_id,'offering_id',v_offering.id,'teacher_id',p_teacher_id,'allocation_role',p_allocation_role));
 return v_id;
end $$;
create or replace function public.get_my_marks_roster(p_term_id uuid)
returns jsonb language sql stable security definer set search_path=public,pg_temp as $$
select coalesce(jsonb_agg(jsonb_build_object('allocationId',ta.id,'offeringId',co.id,'classId',c.id,'className',c.class_name,'streamId',co.stream_id,'streamName',st.stream_name,'subjectCode',coalesce(so.school_subject_code,ss.subject_code),'subjectName',coalesce(so.display_name_override,ss.subject_name),'learners',(select coalesce(jsonb_agg(jsonb_build_object('id',l.id,'admissionNumber',l.admission_number,'name',concat_ws(' ',l.first_name,l.other_name,l.last_name)) order by l.last_name,l.first_name),'[]'::jsonb) from public.learner_class_enrolments e join public.learners l on l.id=e.learner_id where e.class_id=co.class_id and (co.stream_id is null or e.stream_id=co.stream_id) and e.academic_year_id=co.academic_year_id and e.status='ACTIVE' and e.effective_to is null and l.status='ACTIVE')) order by c.level,c.class_name,ss.subject_name),'[]'::jsonb)
from public.teacher_allocations ta join public.class_subject_offerings co on co.id=ta.class_subject_offering_id join public.academic_classes c on c.id=co.class_id left join public.class_streams st on st.id=co.stream_id join public.school_subject_offerings so on so.id=co.school_subject_offering_id left join public.system_subjects ss on ss.id=so.system_subject_id where ta.teacher_id=public.current_app_user_id() and ta.term_id=p_term_id and ta.status='ACTIVE' and ta.allocation_role in ('PRIMARY_SUBJECT_TEACHER','CO_TEACHER') and co.status='ACTIVE' and so.status='ACTIVE' $$;
revoke all on function public.get_teacher_allocation_setup(uuid),public.assign_teacher_to_offering(uuid,uuid,uuid,text,date),public.get_my_marks_roster(uuid) from public,anon;
grant execute on function public.get_teacher_allocation_setup(uuid),public.assign_teacher_to_offering(uuid,uuid,uuid,text,date),public.get_my_marks_roster(uuid) to authenticated;;
